data.code:
# Create a new node (note, folder, or chat)
POST /api/nodes
{
  "title": "New Note",
  "type": "note",
  "parent_id": "folder-123"
}

# Get node tree structure
GET /api/tree

# Update node properties
PUT /api/nodes/{node_id}
{
  "title": "Updated Title",
  "tags": ["tag1", "tag2"]
}

# Delete a node
DELETE /api/nodes/{node_id}
